import re


def execute(node_id, node_data, context):
    """Preserve native search pagination and return the complete updates page.

    Args:
        node_id: The current node identifier.
        node_data: The script node configuration.
        context: The parsed page fields and workflow parameters.

    Raises:
        ValueError: If the request fails or the expected page is missing.
    """
    if context.get("status") != 200 or not context.get("valid_page"):
        raise ValueError("漫画柜：列表页面不可用或页面结构已变化")
    items = context["items"]
    for item in items:
        item["rating"] = float(item["rating"]) if item["rating"] else None
    page = max(1, int(context.get("page_num") or 1))
    if context["is_search"]:
        pages = [
            int(match.group(1))
            for href in context["pagination"]
            if (match := re.search(r"_p(\d+)\.html", href))
        ]
        context["result"] = {"items": items, "totalPages": max([page] + pages)}
    else:
        context["result"] = {"items": items, "totalPages": 1}

